@inlinable
  @inline(never)
  mutating func coalescedEscapedStringTail<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer, from: Int, to: Int, into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    // The escape that sent us here, decoded first. A decode that cannot fuse has emitted
    // nothing, so falling back to the per-byte states is the same fall-back the run body made.
    guard
      let fused = try self.fusedEscapeEnd(
        base: base, from: i, to: to, coalescing: true, into: &sink
      )
    else {
      self.state = .escape
      return i
    }
    i = fused
    #if arch(arm64)
      var blockwise = true
    #endif
    while true {
      #if arch(arm64)
        // Whole blocks first, wherever there is room for them. What follows is the loop for what
        // the block path leaves -- the end of the value, the end of the chunk, anything with a
        // diagnostic, the rest of a run too long for a block to pay -- and it turns the block path
        // back on after a run of 64 bytes or more, which is the end of the long run it was handed.
        if blockwise {
          blockwise = false
          i = try self.coalescedEscapedBlocks(base: base, from: i, to: to, into: &sink)
        }
      #endif
      // The scan stores each block it reads behind `bufferCount`, so a run is in the buffer by the
      // time its end is known (`streamStringRunStaging`). Staged bytes count for nothing until
      // `bufferCount` moves over them, which is after the checks that can throw. Staging stops
      // where the buffer's capacity or the chunk does; what is left of the run goes the old way,
      // behind the staged part, where `bufferStringRun` flushes before it copies.
      let at = Int(self.bufferCount)
      let scan = streamStringRunStaging(
        base: base, from: i, to: to, staging: UnsafeMutableRawPointer(self.bufferBase + at),
        room: Int(self.bufferCapacity) &- at
      )
      let run = scan.run
      let end = run.end

      if end > i {
        if self.highSurrogate != 0 {
          throw Self.loneHighSurrogateError(byteOffset: self.consumedByteCount &+ i)
        }
        let emitEnd = end == to ? try self.trimmingIncompleteUTF8(base: base, from: i, to: end) : end
        if emitEnd > i {
          try self.validateUTF8IfNeeded(
            base: base, from: i, to: emitEnd, containsNonASCII: run.containsNonASCII, reportAt: nil
          )
          let count = emitEnd &- i
          #if arch(arm64)
            blockwise = count >= 64
          #endif
          let staged = Swift.min(scan.staged, count)
          self.bufferCount &+= UInt32(staged)
          if staged < count {
            try self.bufferStringRun(
              base: base, from: i &+ staged, count: count &- staged, end: emitEnd, to: to,
              into: &sink
            )
          }
        }
        if emitEnd < end {
          try self.holdPendingUTF8(base: base, from: emitEnd, to: end)
        }
        i = end
      }

      guard i < to else {
        try self.flushStringBuffer(into: &sink, end: i)
        return i
      }

      let byte = base.load(fromByteOffset: i, as: UInt8.self)
      let byteAt = i
      i &+= 1
      if byte == .asciiQuote {
        if self.highSurrogate != 0 {
          throw Self.loneHighSurrogateError(byteOffset: self.consumedByteCount &+ byteAt)
        }
        try self.flushStringBuffer(into: &sink, end: byteAt)
        try self.record(.stringEnd, start: byteAt, length: 1, end: i, base: base, into: &sink)
        self.state = .afterValue
        return try self.fuseAfterValue(base: base, from: i, to: to, into: &sink)
      } else if byte == .asciiBackslash {
        if let next = try self.fusedEscapeEnd(
          base: base, from: i, to: to, coalescing: true, into: &sink
        ) {
          i = next
          continue
        }
        try self.flushStringBuffer(into: &sink, end: i)
        self.state = .escape
        return i
      } else {
        throw self.error(.unterminatedString, at: byteAt)
      }
    }
  }

