JSONParser.swift:finish.code:
@inlinable
  public mutating func finish<Sink: StreamParseSink & ~Copyable>(
    into sink: inout Sink
  ) throws(JSONParsingError) {
    switch self.state {
    case .number:
      try self.emitBufferedNumber(into: &sink, reportAt: 0)
      self.state = .done
    case .value, .firstValue, .key, .firstKey, .afterKey:
      throw self.error(.unexpectedToken, at: 0)
    case .inString, .inKey, .escape, .unicode, .skippingString, .skippingEscape:
      throw self.error(.unterminatedString, at: 0)
    case .literal:
      throw self.error(.invalidLiteral, at: 0)
    case .skipping:
      throw self.error(.unterminatedContainer, at: 0)
    case .afterValue, .done:
      break
    }
    // Everything is emitted; the lifetime signal goes out before the structural checks, which
    // deliver nothing new. `.number` above moves to `.done` *before* these can throw, so a second
    // `finish()` after a caught `unterminatedContainer` raises again rather than re-emitting.
    try self.commitSink(chunkEnd: 0, into: &sink)
    if self.depth > 0 { throw self.error(.unterminatedContainer, at: 0) }
    if self.pendingUTF8Count > 0 { throw self.error(.invalidUTF8, at: 0) }
  }

JSONParser.swift:firstInvalidUTF8.code:
@inlinable
  @inline(__always)
  static func firstInvalidUTF8(base: UnsafeRawPointer, from: Int, to: Int) -> Int {
    var i = from
    while i < to {
      let lead = base.load(fromByteOffset: i, as: UInt8.self)
      if lead < .utf8ContinuationFloor {
        i &+= 1
        continue
      }
      guard lead >= .utf8TwoByteMinimum, lead <= .utf8MaximumLead else { return i }
      let needed = Self.sequenceLength(lead)
      guard i &+ needed <= to else { return i }
      for offset in 1..<needed {
        let continuation = base.load(fromByteOffset: i &+ offset, as: UInt8.self)
        guard continuation >= .utf8ContinuationFloor, continuation < .utf8TwoByteFloor else {
          return i
        }
      }
      let second = base.load(fromByteOffset: i &+ 1, as: UInt8.self)
      switch lead {
      case .utf8ThreeByteFloor:
        guard second >= .utf8ThreeByteLowerBound else { return i }
      case .utf8SurrogateLead:
        guard second <= .utf8SurrogateCeiling else { return i }
      case .utf8FourByteFloor:
        guard second >= .utf8FourByteLowerBound else { return i }
      case .utf8MaximumLead:
        guard second <= .utf8MaximumSecond else { return i }
      default:
        break
      }
      i &+= needed
    }
    return -1
  }

JSONParser.swift:flushStringBuffer.code:
@inlinable
  mutating func flushStringBuffer<Sink: StreamParseSink & ~Copyable>(
    into sink: inout Sink, end: Int
  ) throws(JSONParsingError) {
    let count = Int(self.bufferCount)
    guard count > 0 else { return }
    self.bufferCount = 0
    try self.record(
      .stringChunk, start: 0, length: count, end: end,
      base: UnsafeRawPointer(self.bufferBase), into: &sink
    )
  }

JSONParser.swift:fuseAfterValue.code:
@inlinable
  @inline(__always)
  mutating func fuseAfterValue<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer, from: Int, to: Int, into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    guard self.depth > 0, from < to,
      base.load(fromByteOffset: from, as: UInt8.self) == .asciiComma
    else {
      return from
    }
    let next = streamWhitespaceEnd(base: base, from: from &+ 1, to: to)
    guard next < to else { return from }
    let byte = base.load(fromByteOffset: next, as: UInt8.self)

    if self.topIsObject {
      // The quote is left for the structural run, which reads the key in place and carries on
      // through the colon; entering `.inKey` here would send the key through the buffered path.
      guard byte == .asciiQuote else { return from }
      self.state = .key
      return next
    }

    switch byte {
    case .asciiQuote:
      self.isKeyToken = false
      self.stringBeginPending = true
      self.state = .inString
      return next &+ 1
    case .asciiDash, .asciiZero ... .asciiNine:
      // The first byte of a number belongs to the number, so it is left for `.number` to re-read.
      self.resetNumber()
      self.state = .number
      return next
    default:
      return from
    }
  }

JSONParser.swift:fuseNumberRun.code:
@inlinable
  @inline(never)
  mutating func fuseNumberRun<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    comma: Int,
    to: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var comma = comma
    // The previous run's indentation, the prediction for the next (see below).
    var indent = Int(self.numberRunIndent)
    while true {
      var start = comma &+ 1
      var byte = base.load(fromByteOffset: start, as: UInt8.self)
      if byte == .asciiSpace, start &+ 1 < to {
        start &+= 1
        byte = base.load(fromByteOffset: start, as: UInt8.self)
      }
      if byte <= .asciiSpace {
        // An indented array's run: a newline and the same indentation as the last one. The
        // spaces are counted in one 8-byte load (the zero bytes of `word ^ 0x20...`, trailing in
        // little-endian order), but that count only *checks* the prediction: the next number's
        // address is `start + 1 + indent`, from a register, so the number scan does not wait on
        // the load. Measured: taking the address from the count cost `,\n` arrays 7 cycles a
        // number (IPC 5.9 -> 4.3), and the vector scan cost indented ones 8 (IPC 5.3 -> 3.9).
        // A miss (the first run, a changed indent) takes the scanner, which the compiler cannot
        // fold into the hit. A count of eight means *at least* eight, so a hit on it can land
        // inside the run, where the whitespace check below finishes it. Only exact spaces count,
        // so a control byte in the run is never skipped: it is the byte the checks below stop on.
        // `<`, not `<=`: a hit moves `start` up to `start + 9`, which must still be in the chunk.
        if byte == .asciiLineFeed, start &+ 9 < to {
          let word = UInt64(
            littleEndian: base.loadUnaligned(fromByteOffset: start &+ 1, as: UInt64.self)
          )
          let spaces = (word ^ 0x2020_2020_2020_2020).trailingZeroBitCount &>> 3
          if _fastPath(spaces == indent) {
            start &+= 1 &+ indent
          } else {
            indent = spaces
            self.numberRunIndent = UInt8(truncatingIfNeeded: spaces)
            start = streamWhitespaceEnd(base: base, from: start, to: to)
            guard start < to else { return comma }
          }
          byte = base.load(fromByteOffset: start, as: UInt8.self)
        }
        if byte <= .asciiSpace {
          start = streamWhitespaceEnd(base: base, from: start, to: to)
          guard start < to else { return comma }
          byte = base.load(fromByteOffset: start, as: UInt8.self)
        }
      }
      guard byte == .asciiDash || byte &- .asciiZero < 10 else { return comma }
      let end = streamNumberRunEnd(base: base, from: start, to: to)
      guard end < to else {
        self.resetNumber()
        return ~start
      }
      try self.emitNumber(base: base, from: start, to: end, into: &sink, reportAt: end)
      guard end &+ 1 < to, base.load(fromByteOffset: end, as: UInt8.self) == .asciiComma else {
        return end
      }
      comma = end
    }
  }

JSONParser.swift:fusedEscapeEnd.code:
@inlinable
  @inline(__always)
  mutating func fusedEscapeEnd<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer, from: Int, to: Int, coalescing: Bool, into sink: inout Sink
  ) throws(JSONParsingError) -> Int? {
    guard self.highSurrogate == 0, from < to else { return nil }
    let selector = base.load(fromByteOffset: from, as: UInt8.self)
    guard selector != .asciiLowerU else {
      if coalescing {
        return try self.coalescedUnicodeEscapeEnd(base: base, from: from, to: to, into: &sink)
      }
      return try self.fusedUnicodeEscapeEnd(base: base, from: from, to: to, into: &sink)
    }
    guard let decoded = streamDecodeSimpleEscape(selector) else { return nil }
    if coalescing {
      // A flush here delivers what was buffered *before* the escape, so it reports one past that
      // chunk's last content byte: the backslash, `from &- 1`.
      try self.bufferStringScratch(UInt64(decoded), count: 1, into: &sink, reportAt: from &- 1)
    } else {
      try self.emitDecoded(byte: decoded, into: &sink, reportAt: from)
    }
    return from &+ 1
  }

JSONParser.swift:fusedUnicodeEscapeEnd.code:
