JSONParser.swift:stringRunBody.code:
@inlinable
  @inline(__always)
  mutating func stringRunBody<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    run: StreamStringRun,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    let end = run.end

    if end > i {
      if self.highSurrogate != 0 {
        throw Self.loneHighSurrogateError(byteOffset: self.consumedByteCount &+ i)
      }
      let emitEnd = end == to ? try self.trimmingIncompleteUTF8(base: base, from: i, to: end) : end
      if emitEnd > i {
        try self.validateUTF8IfNeeded(
          base: base,
          from: i,
          to: emitEnd,
          containsNonASCII: run.containsNonASCII,
          reportAt: nil
        )
        try self.record(.stringChunk, start: i, length: emitEnd &- i, end: emitEnd, base: base, into: &sink)
      }
      if emitEnd < end {
        try self.holdPendingUTF8(base: base, from: emitEnd, to: end)
      }
      i = end
    }

    guard i < to else { return i }

    let byte = base.load(fromByteOffset: i, as: UInt8.self)
    let byteAt = i
    i &+= 1
    if byte == .asciiQuote {
      if self.highSurrogate != 0 {
        throw Self.loneHighSurrogateError(byteOffset: self.consumedByteCount &+ byteAt)
      }
      try self.record(.stringEnd, start: byteAt, length: 1, end: i, base: base, into: &sink)
      self.state = .afterValue
      return try self.fuseAfterValue(base: base, from: i, to: to, into: &sink)
    } else if byte == .asciiBackslash {
      // The rest of this value is taken coalesced, out of line: the decode, the surrogate handling
      // and the buffer bookkeeping all leave this function, which cannot afford to grow. A
      // backslash that is the chunk's last byte cannot fuse and is answered here -- measured: the
      // call cost `Twitter escaped - byte by byte` -1.6%. Nothing is buffered yet on this edge.
      guard i < to else {
        self.state = .escape
        return i
      }
      return try self.coalescedEscapedStringTail(base: base, from: i, to: to, into: &sink)
    } else {
      throw self.error(.unterminatedString, at: byteAt)
    }
  }

JSONParser.swift:structuralBlocksFromLad.code:
@inlinable
    @inline(never)
    mutating func structuralBlocksFromLadder<Sink: StreamParseSink & ~Copyable>(
      base: UnsafeRawPointer,
      from: Int,
      to: Int,
      into sink: inout Sink
    ) throws(JSONParsingError) -> Int {
      var state = self.state
      var depth = self.depth
      var containers = self.containers
      defer {
        self.state = state
        self.depth = depth
        self.containers = containers
      }
      let end = try self.consumeStructuralBlocks(
        base: base, from: from, to: to, state: &state, depth: &depth, containers: &containers,
        into: &sink
      )
      guard state.isStructural else { return end }
      return streamWhitespaceEnd(base: base, from: end, to: to)
    }

JSONParser.swift:structuralRun.code:
@_transparent
  @usableFromInline
  mutating func structuralRun<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    blocks: Bool,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    var state = self.state
    var depth = self.depth
    var containers = self.containers
    defer {
      self.state = state
      self.depth = depth
      self.containers = containers
    }
    while i < to {
      // The scan's one-compare fast path, spelled here so the signal below sits behind it: a token
      // with no whitespace in front of it -- every token of a minified document -- pays nothing.
      var byte = base.load(fromByteOffset: i, as: UInt8.self)
      if byte <= .asciiSpace {
        #if arch(arm64) || arch(x86_64)
          // The signal for the block walk: a whitespace byte followed by more whitespace
          // (indentation) or by a quote (a string next), and a whole block ahead. Those are the
          // two scans the walk replaces. A lone separator space in front of a number is neither,
          // and a document made of those (Mesh: 73,024 runs, all one byte, all before numbers)
          // runs faster on the ladder (-7.0% raw / -10.6% typed in the walk), while the same
          // separators in front of strings want the walk (Twitter spaced: -5.0% typed when kept
          // on the ladder). A function of two bytes: a minified document never signals, and
          // nothing is remembered from one block to the next.
          // Exact whitespace, not `<= space`: a stray control byte must reach the ladder's error
          // arm, and the walk hands such a block straight back, so signalling on it would loop.
          // The walk is reached through `structuralBlocksFromLadder`, never with this loop's
          // locals `inout`, and never through a second exit from the loop -- measured: an early
          // `return ~i` to an outer driver cost the typed rows that never signal 2-3%, and the
          // same signal as `i = ~i; break` 5-6% (Canada, Mesh, Twitter spaced), with *fewer*
          // stack accesses than either. Reading the signal off the scan's results instead (run
          // length >= 2, or a quote as the byte it stopped on) spares Mesh a load per number
          // (typed -5.6% -> -3.2%) and lost everywhere else: Canada raw -7.1%, Qwen raw -5.5%,
          // `Pretty printed users - 64B chunks` -10.6%, Qwen typed -1.6%.
          if blocks, i &+ 64 <= to,
            Self.signalsBlockWalk(byte, base.load(fromByteOffset: i &+ 1, as: UInt8.self))
          {
            self.state = state
            self.depth = depth
            self.containers = containers
            do throws(JSONParsingError) {
              i = try self.structuralBlocksFromLadder(base: base, from: i, to: to, into: &sink)
            } catch {
              // The walk wrote the fields back; this loop's `defer` must not undo that.
              state = self.state
              depth = self.depth
              containers = self.containers
              throw error
            }
            state = self.state
            depth = self.depth
            containers = self.containers
            if i == to || !state.isStructural { break }
            byte = base.load(fromByteOffset: i, as: UInt8.self)
          } else {
            // The scan hands back the byte it stopped on, so the dispatch below reads a register
            // instead of reloading the address the scan just tested.
            let scanned = streamWhitespaceEndByte(base: base, from: i, to: to)
            i = scanned.end
            if i == to { break }
            byte = scanned.byte
          }
        #else
          let scanned = streamWhitespaceEndByte(base: base, from: i, to: to)
          i = scanned.end
          if i == to { break }
          byte = scanned.byte
        #endif
      }
      i &+= 1
      // A number is the one token whose first byte belongs to the token itself, so the run ends
      // and the byte is handed back for `.number` to re-read.
      if try self.consumeStructural(
        byte, base: base, cursor: &i, to: to, state: &state, depth: &depth,
        containers: &containers, into: &sink
      ) {
        i &-= 1
        break
      }
      if !state.isStructural { break }
    }
    return i
  }

JSONParser.swift:topIsObject.code:
@inlinable
  @inline(__always)
  var topIsObject: Bool {
    Self.topIsObject(depth: self.depth, containers: self.containers)
  }

@inlinable
  @inline(__always)
  static func topIsObject(depth: Int, containers: UInt64) -> Bool {
    depth > 0 && (containers &>> UInt64(depth &- 1)) & 1 == 1
  }

JSONParser.swift:trimmingIncompleteUTF8.code:
@inlinable
  @inline(__always)
  mutating func trimmingIncompleteUTF8(
    base: UnsafeRawPointer, from: Int, to: Int
  ) throws(JSONParsingError) -> Int {
    var index = to &- 1
    let lowest = Swift.max(from, to &- 4)
    while index >= lowest {
      let byte = base.load(fromByteOffset: index, as: UInt8.self)
      if byte < .utf8ContinuationFloor { return to }
      if byte >= .utf8TwoByteFloor {
        let needed = Self.sequenceLength(byte)
        let available = to &- index
        return available >= needed ? to : index
      }
      index &-= 1
    }
    return to
  }

JSONParser.swift:unicodeEscape.code:
@inlinable
  @inline(__always)
  static func unicodeEscape(
    base: UnsafeRawPointer, from: Int, to: Int
  ) -> (value: UInt32, end: Int)? {
    guard from &+ 5 <= to, let scalar = streamHexQuad(base: base, from: from &+ 1) else {
      return nil
    }
    let end = from &+ 5
    if scalar >= .highSurrogateFloor, scalar <= .highSurrogateCeiling {
      // A pair is twelve bytes and must be complete and well formed to fuse; anything else is a
      // diagnostic for the per-byte path. The bounds test is first, so the load stays in the chunk.
      guard end &+ 6 <= to,
        UInt16(littleEndian: base.loadUnaligned(fromByteOffset: end, as: UInt16.self))
          == streamUnicodeEscapePrefix,
        let low = streamHexQuad(base: base, from: end &+ 2),
        low >= .lowSurrogateFloor, low <= .lowSurrogateCeiling
      else {
        return nil
      }
      let value =
        .utf8ThreeByteCeiling &+ ((scalar &- .highSurrogateFloor) << 10)
        &+ (low &- .lowSurrogateFloor)
      return (value, end &+ 6)
    } else if scalar >= .lowSurrogateFloor, scalar <= .lowSurrogateCeiling {
      // A lone low surrogate is a diagnostic, so it goes to the per-byte path.
      return nil
    }
    return (scalar, end)
  }

JSONParser.swift:unicodeEscapeEnd.code:
@inlinable
  @inline(__always)
  mutating func unicodeEscapeEnd<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer, from: Int, to: Int, into sink: inout Sink
  ) throws(JSONParsingError) -> Int? {
    guard let escape = Self.unicodeEscape(base: base, from: from, to: to) else { return nil }
    // `emitScratch` reports at `reportAt &+ 1`, so `reportAt` must be the escape's *last* byte
    // -- `end &- 1` for a single escape and a surrogate pair alike; `from` reported 4 (10) early.
    try self.emitScalar(escape.value, into: &sink, reportAt: escape.end &- 1)
    return escape.end
  }

JSONParser.swift:utf8Word.code:
@inlinable
  @inline(__always)
  static func utf8Word(_ value: UInt32) -> (word: UInt64, count: Int) {
    let word: UInt64
    let count: Int
    if value < .utf8OneByteCeiling {
      word = UInt64(value)
      count = 1
    } else if value < .utf8TwoByteCeiling {
      word =
        UInt64(0xC0 | (value >> 6))
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 8)
      count = 2
    } else if value < .utf8ThreeByteCeiling {
      word =
        UInt64(0xE0 | (value >> 12))
        | (UInt64(0x80 | ((value >> 6) & .utf8ContinuationMask)) &<< 8)
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 16)
      count = 3
    } else {
      word =
        UInt64(0xF0 | (value >> 18))
        | (UInt64(0x80 | ((value >> 12) & .utf8ContinuationMask)) &<< 8)
        | (UInt64(0x80 | ((value >> 6) & .utf8ContinuationMask)) &<< 16)
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 24)
      count = 4
    }
    return (word, count)
  }

JSONParser.swift:validateNonASCIIRun.code:
@inlinable
  @inline(never)
  mutating func validateNonASCIIRun(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    reportAt: Int?
  ) throws(JSONParsingError) {
    if streamValidateUTF8Inline(base: base, from: from, to: to) { return }
    try Self.failInvalidUTF8(
