JSONParser.swift:validateUTF8IfNeeded.code:
@inlinable
  @inline(__always)
  mutating func validateUTF8IfNeeded(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    containsNonASCII: Bool,
    reportAt: Int?
