PartialSink.swift:matchTableKey.code:
@inline(__always)
  private static func matchTableKey(_ top: UnsafeMutablePointer<BorrowedFrame>, _ key: Span<UInt8>) {
    let length = key.count
    guard length <= Int(UInt16.max) else {
      top.pointee.pendingField = -1
      return
    }
    let word = key._streamPaddedLeadingWord()
    let keyLength = UInt16(truncatingIfNeeded: length)
    let entries = top.pointee.schema.fieldEntries.unsafelyUnwrapped
    if let index = top.pointee.schema.fieldIndex {
      let mask = top.pointee.schema.fieldIndexMask
      var probe = Int(truncatingIfNeeded: streamFieldHash(word: word, length: keyLength)) & mask
      while true {
        let slot = index[probe]
        guard slot >= 0 else {
          top.pointee.pendingField = -1
          return
        }
        let entry = entries + Int(slot)
        if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength {
          guard length <= 8 else {
            Self.matchTableKeyTail(top, key, indexedFrom: probe)
            return
          }
          top.pointee.pendingField = slot
          return
        }
        probe = (probe &+ 1) & mask
      }
    }
    let count = top.pointee.schema.fieldCount
    var position = 0
    while position < count {
      let entry = entries + position
      if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength {
        guard length <= 8 else {
          Self.matchTableKeyTail(top, key, linearFrom: position)
          return
        }
        top.pointee.pendingField = Int32(truncatingIfNeeded: position)
        return
      }
      position &+= 1
    }
    top.pointee.pendingField = -1
  }

PartialSink.swift:matchTableKeyTail.code:
@inline(never)
  private static func matchTableKeyTail(
    _ top: UnsafeMutablePointer<BorrowedFrame>, _ key: Span<UInt8>, linearFrom start: Int
  ) {
    let word = key._streamPaddedLeadingWord()
    let keyLength = UInt16(truncatingIfNeeded: key.count)
    let entries = top.pointee.schema.fieldEntries.unsafelyUnwrapped
    let keyBytes = top.pointee.schema.fieldKeyBytes.unsafelyUnwrapped
    let count = top.pointee.schema.fieldCount
    var position = start
    while position < count {
      let entry = entries + position
      if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength
        && Self.longKeyTailMatches(entry, keyBytes: keyBytes, key)
      {
        top.pointee.pendingField = Int32(truncatingIfNeeded: position)
        return
      }
      position &+= 1
    }
    top.pointee.pendingField = -1
  }

@inline(never)
  private static func matchTableKeyTail(
    _ top: UnsafeMutablePointer<BorrowedFrame>, _ key: Span<UInt8>, indexedFrom start: Int
  ) {
    let word = key._streamPaddedLeadingWord()
    let keyLength = UInt16(truncatingIfNeeded: key.count)
    let entries = top.pointee.schema.fieldEntries.unsafelyUnwrapped
    let keyBytes = top.pointee.schema.fieldKeyBytes.unsafelyUnwrapped
    let index = top.pointee.schema.fieldIndex.unsafelyUnwrapped
    let mask = top.pointee.schema.fieldIndexMask
    var probe = start
    while true {
      let slot = index[probe]
      guard slot >= 0 else {
        top.pointee.pendingField = -1
        return
      }
      let entry = entries + Int(slot)
      if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength
        && Self.longKeyTailMatches(entry, keyBytes: keyBytes, key)
      {
        top.pointee.pendingField = slot
        return
      }
      probe = (probe &+ 1) & mask
    }
  }

PartialSink.swift:null.code:
public mutating func null() {
    if self.topFrame == nil, !self.started {
      let result = self.rootSchema.applyNull(self.root, StreamSchema.wholeValueField)
      if result != .applied {
        self.recordFailure(Self.failureReason(for: result))
      }
      return
    }
    switch self.activeLeafRoute {
    case .arrayOptionalStreamString, .arrayOptionalBool,
      .arrayOptionalDouble, .arrayOptionalInt,
      .dictionaryOptionalStreamString, .dictionaryOptionalBool:
      self.applyKnownNull(self.activeLeafRoute)
      return
    case .simd2Number, .simd3Number, .simd4Number,
      .simd2Double, .simd3Double, .simd4Double,
      .optionalSIMD2Double, .optionalSIMD3Double, .optionalSIMD4Double:
      self.recordFailure(.typeMismatch)
      return
    default:
      if self.activeElementKindBits != 0 {
        self.applyKnownNull()
        return
      }
      // The pairing, as in `number` above. `container` joins `custom` on the closure route: a
      // null for a container member nils the optional through the schema.
      if let top = self.topFrame, top.pointee.schema.shape == .object {
        let field = top.pointee.pendingField
        switch top.pointee.schema.keyRouting {
        case .table:
          if field >= 0 {
            let entry = top.pointee.schema.fieldEntries.unsafelyUnwrapped + Int(field)
            let kind = entry.pointee.kind
            let result =
              kind == .custom || kind == .container
              ? top.pointee.schema.applyNull(top.pointee.storage, entry.pointee.index)
              : kind == .delegated
                ? Self.delegateNull(entry, top.pointee.storage + Int(entry.pointee.offset))
                : Self.writeTableNull(entry, member: top.pointee.storage + Int(entry.pointee.offset))
            if result != .applied { self.recordFailure(Self.failureReason(for: result)) }
          }
          return
        case .match:
          if field >= 0 {
            let result = top.pointee.schema.applyNull(top.pointee.storage, field)
            if result != .applied { self.recordFailure(Self.failureReason(for: result)) }
          }
          return
        default:
          break
        }
      }
      self.applyNullNormally()
      return
    }
  }

