      self.pushSIMDDoubleFrame(storage, _streamSIMD2DoubleSchema, lanes: .simd2Double)
    case .arrayOptionalSIMD3Double:
      let storage = top.pointee.storage.assumingMemoryBound(
        to: StreamArray<SIMD3<Double>?>.self
