      self.pendingDictionaryStorage = nil
      return pending
    case .dictionaryOptionalStreamString:
      guard let pending = self.pendingDictionaryStorage else { return nil }
      self.pendingDictionaryStorage = nil
      _streamMaterializeOptional(pending, as: StreamString.self)
      return pending
    default:
      return nil
    }
  }

