@inline(__always)
  private mutating func openSIMDDoubleElementIfReady<Vector: SIMD>(
    _ type: Vector.Type, lanes route: _StreamLeafRoute
  ) -> Bool where Vector.Scalar == Double {
    // The route word is the top frame's, so the stack is not empty.
    let top = self.frameEnd - 1
    guard self.frameEnd < self.frames + Self.frameCapacity,
      let schemaBits = top.pointee.schema.elementSchemaBits,
      let storage = top.pointee.storage.assumingMemoryBound(to: StreamArray<Vector>.self).pointee
        .openElementIfReady(.zero, knownUniqueTail: self.knownUniqueTail)
    else { return false }
    let bits = StreamRouteBits.pack(leafRoute: route, elementKind: .double, elementOptional: false)
    var frame = BorrowedFrame(storage: storage, schemaBits: schemaBits)
    assert(frame.schema.routeBits == bits && frame.schema.completedValue == nil)
    frame.pendingField = 0
    frame.routeBits = bits
    self.frameEnd.initialize(to: frame)
    self.frameEnd += 1
    self.activeRouteBits = bits
    return true
  }

PartialSink.swift:openTableString.code:
@inline(never)
  private mutating func openTableString(
    _ entry: UnsafePointer<StreamFieldEntry>,
    _ storage: UnsafeMutableRawPointer
  ) -> StreamApplyResult {
    // Ahead of the switch, as in `number`, and behind the schema word rather than the kind: a
    // fourth arm, or a kind test SimplifyCFG folds into one, turns its compare chain into a jump
    // table. No string kind the table writes carries a schema.
    if entry.pointee.schemaBits != nil, entry.pointee.kind == .delegated {
      return self.openDelegatedString(entry, storage)
    }
    switch entry.pointee.kind {
    case .streamString:
      if entry.pointee.isOptional {
        _streamMaterializeOptional(storage, as: StreamString.self)
      }
      if entry.pointee.capacity > 0 {
        storage.assumingMemoryBound(to: StreamString.self).pointee
          .streamReserve(utf8ByteCount: Int(entry.pointee.capacity))
      }
      self.homogeneousStringStorage = storage
      self.scalarTarget = nil
      return .applied
    case .custom:
      // The closure route, exactly as before the table: the empty span materialises and settles.
      let target = self.scalarTarget.unsafelyUnwrapped
      let field = entry.pointee.index
      let info = StringInfo(flags: self.stringFlags.union(.begin))
      return target.withSchema { $0.applyString(storage, field, Span(), info) }
    default:
      return .unsupported
    }
  }

PartialSink.swift:popFrame.code:
@usableFromInline
  mutating func popFrame() {
    guard self.droppedFrameCount == 0 else {
      self.droppedFrameCount &-= 1
      return
    }
    guard self.frameEnd != self.frames else { return }
    if !self.completedValues.isEmpty { self.finishCompletedValues() }
    self.frameEnd -= 1
    self.frameEnd.deinitialize(count: 1)
    self.activeRouteBits = self.frameEnd == self.frames
      ? 0
      : (self.frameEnd - 1).pointee.routeBits
  }

PartialSink.swift:pushFrame.code:
@usableFromInline
  mutating func pushFrame(_ initialFrame: BorrowedFrame) {
    // `<`, not `!=`: once the ignored frame fills the overflow slot, `frameEnd` sits one past
    // `frameCapacity`, and an equality test would let the next container push out of bounds.
    guard self.frameEnd < self.frames + Self.frameCapacity else {
      self.pushOverflowFrame()
      return
    }
    var frame = initialFrame
    if frame.withSchema({ $0.completedValue != nil }) {
      frame = self.openCompletedValue(frame)
    }
    frame.routeBits = frame.schema.routeBits
    if frame.leafRoute.usesFrameElementIndex {
      // Objects use this field for a matched member. A fixed-width array has no keys, so the same
      // four bytes are its element cursor without increasing the 24-byte frame.
      frame.pendingField = 0
    }
    self.frameEnd.initialize(to: frame)
    self.frameEnd += 1
    self.activeRouteBits = frame.routeBits
  }

PartialSink.swift:pushOverflowFrame.code:
@usableFromInline
  @inline(never)
  mutating func pushOverflowFrame() {
    self.recordFailure(.depthExceeded)
    guard self.frameEnd < self.frames + Self.overflowCapacity else {
      // Already inside an ignored subtree: the top frame discards, so deeper containers only have
      // to stay balanced against `popFrame`.
      self.droppedFrameCount &+= 1
      return
    }
    var frame = self.ignoredFrame
    frame.routeBits = frame.schema.routeBits
    self.frameEnd.initialize(to: frame)
    self.frameEnd += 1
    self.activeRouteBits = frame.routeBits
  }

