        return
      }
      let streamDefaultValue = \(payload.typeName).Value(
        orInitial: partial.\(name) ?? \(payload.typeName).Partial.streamInitialValue()
      )
      self = .\(name)(\(Self.caseArguments(payload, from: "streamDefaultValue")))
