StreamFieldTable.swift:StreamFieldKind.code:
public enum StreamFieldKind: UInt8, Sendable {
  /// A conforming type the library has no layout for, applied through the schema's closures with
  /// the entry's `index`.
  case custom = 0
  case int
  case int8
  case int16
  case int32
  case int64
  case uint
  case uint8
  case uint16
  case uint32
  case uint64
  case double
  case float
  case bool
  /// `StreamString`, appended in place; `capacity` is the reservation to make at the opening
  /// quote when the member carries one.
  case streamString
  /// An object, array, dictionary or fixed-width vector. Entered from the entry when it carries the
  /// child's `schema` (after its `prepare`, if any), through the schema's `enterField` closure with
  /// the entry's `index` when it does not. A scalar arriving here is a type mismatch.
  case container
  /// A scalar member whose type the macro could not see -- a generic parameter's `Partial` -- and
  /// whose schema has no kind the table writes. Applied through the entry's own `schema` at the
  /// member's address with `wholeValueField`, never through the parent's closures, so a generic
  /// `Partial` needs no stored static to reach its child's schema from. Last, so `isNumber`'s range
  /// is untouched.
  case delegated

  @inlinable
  public var isNumber: Bool {
    self.rawValue >= StreamFieldKind.int.rawValue && self.rawValue <= StreamFieldKind.float.rawValue
  }
}

