private static func requireDistinctKeys(_ fields: [StreamField]) {
    for later in fields.indices {
      for earlier in 0..<later where fields[earlier].key == fields[later].key {
        #if hasFeature(Embedded)
          preconditionFailure("stream field key is claimed by more than one field")
        #else
          let key = String(decoding: fields[later].key, as: UTF8.self)
          preconditionFailure("stream field key '\(key)' is claimed by more than one field")
        #endif
      }
    }
  }

StreamFieldTable.swift:streamFieldHash.code:
@inlinable
@inline(__always)
func streamFieldHash(word: UInt64, length: UInt16) -> UInt64 {
  var z = word ^ (UInt64(length) &<< 56)
  z = (z ^ (z >> 33)) &* 0xff51afd7ed558ccd
  z = (z ^ (z >> 33)) &* 0xc4ceb9fe1a85ec53
  z = z ^ (z >> 33)
  return z
}

StreamFieldTable.swift:streamFieldTailMa.code:
@usableFromInline
@inline(never)
func streamFieldTailMatches(
  _ entry: UnsafePointer<StreamFieldEntry>, keyBytes: UnsafePointer<UInt8>, _ key: Span<UInt8>
) -> Bool {
  key.withUnsafeBufferPointer { buffer in
    // The first word already matched, and the key is longer than a word, so `count - 8` is a
    // byte offset of both keys (the stored one has the same length) and the last word read from
    // it ends exactly at their ends: words from 8 while one fits short of it, then that last
    // word, overlapping what came before. No byte loop and no read past either key.
    let stored = UnsafeRawPointer(keyBytes + Int(entry.pointee.keyStart))
    let given = UnsafeRawPointer(buffer.baseAddress.unsafelyUnwrapped)
    let last = buffer.count &- 8
    var offset = 8
    while offset < last {
      if stored.loadUnaligned(fromByteOffset: offset, as: UInt64.self)
        != given.loadUnaligned(fromByteOffset: offset, as: UInt64.self)
      {
        return false
      }
      offset &+= 8
    }
    return stored.loadUnaligned(fromByteOffset: last, as: UInt64.self)
      == given.loadUnaligned(fromByteOffset: last, as: UInt64.self)
  }
}

StreamFieldTable.swift:streamMatchField.code:
@inlinable
@inline(__always)
func streamMatchField(
  _ entries: UnsafePointer<StreamFieldEntry>,
  count: Int,
  keyBytes: UnsafePointer<UInt8>,
  _ key: Span<UInt8>
) -> Int32 {
  let length = key.count
  guard length <= Int(UInt16.max) else { return -1 }
  let word = key._streamPaddedLeadingWord()
  let keyLength = UInt16(truncatingIfNeeded: length)
  var index = 0
  while index < count {
    let entry = entries + index
    if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength {
      if length <= 8 || streamFieldTailMatches(entry, keyBytes: keyBytes, key) {
        return Int32(truncatingIfNeeded: index)
      }
    }
    index &+= 1
  }
  return -1
}

StreamFieldTable.swift:streamMatchFieldI.code:
@inlinable
@inline(__always)
func streamMatchFieldIndexed(
  _ entries: UnsafePointer<StreamFieldEntry>,
  index: UnsafePointer<Int32>,
  mask: Int,
  keyBytes: UnsafePointer<UInt8>,
  _ key: Span<UInt8>
) -> Int32 {
  let length = key.count
  guard length <= Int(UInt16.max) else { return -1 }
  let word = key._streamPaddedLeadingWord()
  let keyLength = UInt16(truncatingIfNeeded: length)
  let hash = streamFieldHash(word: word, length: keyLength)
  var probe = Int(truncatingIfNeeded: hash) & mask
  while true {
    let slot = index[probe]
    guard slot >= 0 else { return -1 }
    let entry = entries + Int(slot)
    if entry.pointee.keyWord == word && entry.pointee.keyLength == keyLength {
      if length <= 8 || streamFieldTailMatches(entry, keyBytes: keyBytes, key) {
        return slot
      }
    }
    probe = (probe &+ 1) & mask
  }
}

