@inlinable
@inline(__always)
package func streamAccumulateLeadingDigits(
  biased: UInt64, nonDigit: UInt64, into magnitude: inout UInt64
) -> Int {
  let bits = nonDigit.trailingZeroBitCount & 0x38
  let value = streamEightDigitValue((biased &<< UInt64(truncatingIfNeeded: 63 &- bits)) &<< 1)
  magnitude =
    magnitude &* stream_parsing_pow10_u64(UInt32(truncatingIfNeeded: bits &>> 3)) &+ value
  return bits &>> 3
}

StreamScanners.swift:streamBytesAreASCII.code:
@inlinable
@inline(__always)
package func streamBytesAreASCII(_ base: UnsafeRawPointer, count: Int) -> Bool {
  var i = 0
  var lanes = SIMD16<UInt8>.zero
  while i &+ 16 <= count {
    lanes |= base.loadUnaligned(fromByteOffset: i, as: SIMD16<UInt8>.self)
    i &+= 16
  }
  var tail: UInt64 = 0
  while i < count {
    let width = Swift.min(count &- i, 8)
    tail |= streamPaddedWord(base: base, from: i, to: i &+ width)
    i &+= width
  }
  let words = unsafeBitCast(lanes, to: SIMD2<UInt64>.self)
  return (words[0] | words[1] | tail) & 0x8080_8080_8080_8080 == 0
}

