  let lowCount = UInt64(littleEndian: words[0]).trailingZeroBitCount
  let highCount = UInt64(littleEndian: words[1]).trailingZeroBitCount
  let lowEmpty = 0 &- (lowCount &>> 6)
  return (lowCount &>> 3) &+ ((highCount &>> 3) & lowEmpty)
}

