StreamScanners.swift:streamHashBytes.code:
@inlinable
@inline(__always)
package func streamHashBytes(base: UnsafeRawPointer, count: Int) -> UInt64 {
  let prime0: UInt64 = 0x9E37_79B9_7F4A_7C15
  let prime1: UInt64 = 0xC2B2_AE3D_27D4_EB4F

  var a = prime0 ^ UInt64(UInt(bitPattern: count))
  var b = prime1

  var i = 0
  while i &+ 16 <= count {
    let block = unsafeBitCast(
      base.loadUnaligned(fromByteOffset: i, as: SIMD16<UInt8>.self), to: SIMD2<UInt64>.self
    )
    a = (a ^ block[0]) &* prime0
    b = (b ^ block[1]) &* prime1
    i &+= 16
  }

  if i < count {
    let width = Swift.min(count &- i, 8)
    a = (a ^ streamPaddedWord(base: base, from: i, to: i &+ width)) &* prime0
    i &+= width
    if i < count {
      b = (b ^ streamPaddedWord(base: base, from: i, to: count)) &* prime1
    }
  }

  // Avalanche, so that keys differing in one byte land in different buckets rather than in
  // adjacent ones: the table masks the low bits and linear probing punishes clustering.
  var hash = a ^ b
  hash ^= hash >> 33
  hash = hash &* 0xFF51_AFD7_ED55_8CCD
  hash ^= hash >> 29
  return hash
}

StreamScanners.swift:streamHexQuad.code:
@inlinable
@inline(__always)
package func streamHexQuad(base: UnsafeRawPointer, from: Int) -> UInt32? {
  let bytes = UInt32(littleEndian: base.loadUnaligned(fromByteOffset: from, as: UInt32.self))
  let tops: UInt32 = 0x8080_8080
  let folded = bytes | 0x2020_2020
  // `b + 0x50` reaches 0x80 at '0'; `b + 0x46` at ':'. `f + 0x1F` at 'a'; `f + 0x19` at 'g'.
  let digit = (bytes &+ 0x5050_5050) & ~(bytes &+ 0x4646_4646)
  let letter = (folded &+ 0x1F1F_1F1F) & ~(folded &+ 0x1919_1919)
  guard (digit | letter) & ~bytes & tops == tops else { return nil }
  let nibbles = (bytes & 0x0F0F_0F0F) &+ ((bytes >> 6) & 0x0101_0101) &* 9
  // First character is the low byte and the most significant digit: pair each even byte with
  // the odd byte above it, then put the two pairs in order.
  let pairs = (nibbles << 4) | (nibbles >> 8)
  return ((pairs & 0xFF) << 8) | ((pairs >> 16) & 0xFF)
}

