StreamSchemaCache.swift:schema.code:
@inlinable
  public func schema<T: StreamPartial>(
    for type: T.Type,
    usage: StreamSchema.Usage = .root,
    build: () -> StreamSchema
  ) -> StreamSchema {
    #if hasFeature(Embedded)
      build()
    #else
      self.schema(for: Key(type: ObjectIdentifier(type), usage: usage), build: build)
    #endif
  }

@usableFromInline
    func schema(for key: Key, build: () -> StreamSchema) -> StreamSchema {
      if let cached = self.lock.withLock({ _ in self.entries[key]?.cached }) {
        return cached
      }
      let owned = self.lock.withLock { _ in self.entries[key]?.build }
      let built = owned?() ?? build()
      return self.lock.withLock { _ in self.entry(for: key).storeLocked(built) }
    }

public var schema: StreamSchema {
      #if hasFeature(Embedded)
        if let pointer = self.published.load(ordering: .acquiring) {
          return Unmanaged<StreamSchema>.fromOpaque(pointer).takeUnretainedValue()
        }
      #else
        if let cached = self.lock.withLock({ _ in self.cached }) { return cached }
      #endif
      return self.store(self.build.unsafelyUnwrapped())
    }

StreamSchemaCache.swift:store.code:
func store(_ built: StreamSchema) -> StreamSchema {
      #if hasFeature(Embedded)
        let retained = UnsafeRawPointer(Unmanaged.passRetained(built).toOpaque())
        let (exchanged, original) = self.published.compareExchange(
          expected: nil, desired: retained, ordering: .acquiringAndReleasing
        )
        if exchanged { return built }
        Unmanaged<StreamSchema>.fromOpaque(retained).release()
        return Unmanaged<StreamSchema>.fromOpaque(original.unsafelyUnwrapped).takeUnretainedValue()
      #else
        self.lock.withLock { _ in self.storeLocked(built) }
      #endif
    }

StreamSchemaCache.swift:storeLocked.code:
func storeLocked(_ built: StreamSchema) -> StreamSchema {
        if let existing = self.cached { return existing }
        self.cached = built
        return built
      }

StreamString+Reading.swift:characterSpan.code:
@usableFromInline
  func characterSpan(at offset: Int) -> (character: Character, end: Int) {
    var windowEnd = self.scalarAlignedOffset(before: min(offset &+ 8, self.utf8Count))
    if windowEnd <= offset { windowEnd = min(offset &+ 4, self.utf8Count) }
    while true {
      let window = self.decode(in: offset..<windowEnd)
      let first = window.first ?? "\u{FFFD}"
      var end = offset &+ first.utf8.count
      // A decode that did not round-trip its byte count repaired something, so the character's
      // decoded length is not its byte length: walk its scalars back through the same repair.
      // Returning after one scalar instead re-read a multi-scalar character's tail as the next
      // character (`e\u{301}` then `\u{301}` again).
      if window.utf8.count != windowEnd &- offset {
        end = offset
        for _ in first.unicodeScalars { end &+= self.decodeScalar(at: end).length }
      }
      if end < windowEnd || windowEnd == self.utf8Count { return (first, end) }
      let grown = self.scalarAlignedOffset(
        before: min(offset &+ (windowEnd &- offset) &* 2, self.utf8Count)
      )
      guard grown > windowEnd else { return (first, end) }
      windowEnd = grown
    }
  }

StreamString+Reading.swift:scalarIndex.code:
@usableFromInline
  func scalarIndex(before index: Int) -> Int {
    var candidate = index &- 1
    var steps = 0
    while steps < 3, candidate > 0, self.utf8Byte(at: candidate) & 0xC0 == 0x80 {
      candidate &-= 1
      steps &+= 1
    }
    return candidate &+ self.decodeScalar(at: candidate).length >= index ? candidate : index &- 1
  }

