    let shift = self.startBlockShift
    let ramp = min(block, Self.maximumBlockShift &- shift)
    return (1 &<< (shift &+ ramp)) &- (1 &<< shift)
      &+ ((block &- ramp) &<< Self.maximumBlockShift)
  }

